use vstd::prelude::*;

verus! {

spec fn all_ones(v: Seq<i32>) -> bool {
    forall|i: int| 0 <= i < v.len() ==> v[i] == 1
}

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        all_ones(result@),
{
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;
    let len = a.len();

    while i < len
        invariant
            i <= len,
            len == a.len(),
            result.len() == i,
            all_ones(result@),
    {
        result.push(1);
        i += 1;
    }

    result
}

}

